ROOT = Path(__file__).resolve().parent
DB = ROOT / "data" / "mova_materials.sqlite3"
OUT = Path.home() / "Desktop" / "FB单素材表现看板"
XLSX = OUT / "FB单素材历史表现_v1.xlsx"
HTML = OUT / "FB单素材Dashboard_v1.html"
DB_COPY = OUT / "mova_materials.sqlite3"

def q(conn, sql): return [dict(r) for r in conn.execute(sql)]

def build_excel(rows, daily, creatives, accounts):
    wb=Workbook(); ws=wb.active; ws.title="看板"
    navy="17233D"; blue="3478F6"; pale="EAF1FF"; green="22A06B"; orange="F5A623"
    ws.merge_cells("A1:H2"); ws["A1"]="Meta / Facebook 单素材历史表现"; ws["A1"].font=Font(size=22,bold=True,color="FFFFFF"); ws["A1"].fill=PatternFill('solid',fgColor=navy); ws["A1"].alignment=Alignment(vertical="center")
    totals={k:sum(float(r.get(k) or 0) for r in rows) for k in ["spend","impressions","clicks","app_installs","purchases","purchase_value"]}
    cards=[("覆盖日期",f"{rows[0]['report_date']} ~ {rows[-1]['report_date']}"),("花费",totals['spend']),("展示",totals['impressions']),("点击",totals['clicks']),("安装",totals['app_installs']),("购买",totals['purchases']),("收入",totals['purchase_value']),("ROAS",totals['purchase_value']/totals['spend'] if totals['spend'] else 0)]
    for i,(label,val) in enumerate(cards,1): ws.cell(4,i,label); ws.cell(5,i,val); ws.cell(4,i).fill=PatternFill('solid',fgColor=pale); ws.cell(4,i).font=Font(bold=True,color=navy); ws.cell(5,i).font=Font(size=14,bold=True,color=blue)
    ws["A8"]="日期"; ws["B8"]="花费"; ws["C8"]="收入"; ws["D8"]="安装"; ws["E8"]="购买"
    for j,h in enumerate(["日期","花费","收入","安装","购买"],1): ws.cell(8,j,h).fill=PatternFill('solid',fgColor=navy); ws.cell(8,j).font=Font(color="FFFFFF",bold=True)
    for i,r in enumerate(daily,9):
        ws.cell(i,1,r["report_date"]); ws.cell(i,2,r["spend"]); ws.cell(i,3,r["revenue"]); ws.cell(i,4,r["installs"]); ws.cell(i,5,r["purchases"])
    line=LineChart(); line.title="每日花费与收入趋势"; line.add_data(Reference(ws,min_col=2,max_col=3,min_row=8,max_row=8+len(daily)),titles_from_data=True); line.set_categories(Reference(ws,min_col=1,min_row=9,max_row=8+len(daily))); line.height=8; line.width=16; ws.add_chart(line,"J4")
    ws["G8"]="素材"; ws["H8"]="花费"; ws["I8"]="ROAS"
    for j,h in enumerate(["素材","花费","ROAS"],7): ws.cell(8,j,h).fill=PatternFill('solid',fgColor=navy); ws.cell(8,j).font=Font(color="FFFFFF",bold=True)
    for i,r in enumerate(creatives[:15],9): ws.cell(i,7,r["ad_name"]); ws.cell(i,8,r["spend"]); ws.cell(i,9,r["roas"])
    bar=BarChart(); bar.title="Top 15 素材花费"; bar.add_data(Reference(ws,min_col=8,min_row=8,max_row=8+min(15,len(creatives))),titles_from_data=True); bar.set_categories(Reference(ws,min_col=7,min_row=9,max_row=8+min(15,len(creatives)))); bar.height=8; bar.width=16; ws.add_chart(bar,"J20")
    ws.freeze_panes="A9"; ws.column_dimensions['A'].width=14
    for c in "BCDEFGHI": ws.column_dimensions[c].width=18
    ws.column_dimensions['G'].width=48

    raw=wb.create_sheet("日明细")
    headers=["日期","账户","Campaign","Ad Set","广告ID","广告/素材名","Creative ID","花费","展示","触达","点击","CTR","CPM","CPC","安装","注册","购买","收入","ROAS","视频播放","ThruPlay","25%","50%","75%","100%","当日未完结"]
    raw.append(headers)
    for r in rows:
        raw.append([r["report_date"],r["account_name"],r["campaign_name"],r["adset_name"],r["ad_id"],r["ad_name"],r["creative_id"],r["spend"],r["impressions"],r["reach"],r["clicks"],r["ctr"],r["cpm"],r["cpc"],r["app_installs"],r["registrations"],r["purchases"],r["purchase_value"],f"=IFERROR(R{raw.max_row+1}/H{raw.max_row+1},0)",r["video_plays"],r["thruplays"],r["video_p25"],r["video_p50"],r["video_p75"],r["video_p100"],r["is_partial_day"]])
    raw.freeze_panes="A2"; raw.auto_filter.ref=raw.dimensions
    for cell in raw[1]: cell.fill=PatternFill('solid',fgColor=navy); cell.font=Font(color="FFFFFF",bold=True)
    raw.column_dimensions['A'].width=12; raw.column_dimensions['B'].width=28; raw.column_dimensions['C'].width=30; raw.column_dimensions['D'].width=30; raw.column_dimensions['F'].width=55
    raw.conditional_formatting.add(f"S2:S{raw.max_row}",ColorScaleRule(start_type='min',start_color='FEE2E2',mid_type='percentile',mid_value=50,mid_color='FFF7CC',end_type='max',end_color='DCFCE7'))
    sm=wb.create_sheet("素材汇总"); sm.append(["素材名","广告ID","首日","末日","活跃天数","花费","展示","点击","CTR","安装","购买","收入","ROAS","CPI","CPA"])
    for r in creatives: sm.append([r["ad_name"],r["ad_id"],r["first_date"],r["last_date"],r["days"],r["spend"],r["impressions"],r["clicks"],r["ctr"],r["installs"],r["purchases"],r["revenue"],r["roas"],r["cpi"],r["cpa"]])
    sm.freeze_panes="A2"; sm.auto_filter.ref=sm.dimensions; sm.column_dimensions['A'].width=60
    for c in sm[1]: c.fill=PatternFill('solid',fgColor=navy); c.font=Font(color="FFFFFF",bold=True)
    ac=wb.create_sheet("账户汇总"); ac.append(["账户","首日","末日","花费","展示","点击","安装","购买","收入","ROAS"])
    for r in accounts: ac.append(list(r.values()))
    dd=wb.create_sheet("口径说明"); notes=[("字段","说明"),("时间口径","Asia/Shanghai；今天标记为未完结，不宜与完整自然日直接比较"),("归因窗口","Meta 7天点击 + 1天浏览"),("素材粒度","以 ad_id 为稳定主键，同时保留 creative_id；同一创意复用到多个广告时可再聚合"),("安装/购买","优先读取 mobile_app_install / purchase，别名仅作回退，避免重复求和"),("收入/ROAS","Meta action_values 的 purchase value；ROAS=收入/花费，不等同 AppsFlyer 最终归因口径"),("v1覆盖","本轮在执行时限内已完成的账户数据；同步脚本支持重复执行补齐")]
    for x in notes: dd.append(x)
    dd.column_dimensions['A'].width=20; dd.column_dimensions['B'].width=100; dd.freeze_panes="A2"
    for s in wb.worksheets:
        s.sheet_view.showGridLines=False
        for row in s.iter_rows():
            for c in row: c.alignment=Alignment(vertical="top",wrap_text=False)
    OUT.mkdir(parents=True,exist_ok=True); wb.save(XLSX)

def build_html(rows, daily, creatives, accounts):
    data=json.dumps({"rows":rows,"daily":daily,"creatives":creatives,"accounts":accounts},ensure_ascii=False,separators=(",",":"))
    html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>FB单素材Dashboard</title><style>
    :root{--bg:#08111f;--panel:#111e33;--line:#253654;--text:#edf4ff;--muted:#8fa6c6;--blue:#5b8cff;--green:#29d391;--orange:#ffb15c}*{box-sizing:border-box}body{margin:0;background:linear-gradient(135deg,#07101d,#0d1b31);color:var(--text);font:14px system-ui,"Microsoft YaHei"}.wrap{max-width:1500px;margin:auto;padding:24px}h1{font-size:28px;margin:0}.sub{color:var(--muted);margin:7px 0 20px}.filters,.cards,.grid{display:grid;gap:12px}.filters{grid-template-columns:repeat(4,1fr);margin-bottom:14px}.cards{grid-template-columns:repeat(6,1fr)}.card,.panel{background:rgba(17,30,51,.92);border:1px solid var(--line);border-radius:14px;padding:16px}.label{color:var(--muted);font-size:12px}.value{font-size:23px;font-weight:750;margin-top:7px}.grid{grid-template-columns:2fr 1fr;margin-top:14px}.panel h2{font-size:15px;margin:0 0 12px}select,input{width:100%;background:#0b1729;border:1px solid var(--line);color:var(--text);padding:10px;border-radius:8px}.chart-wrap{height:320px;position:relative;overflow:hidden}.chart-wrap canvas{width:100%!important;height:100%!important}table{width:100%;border-collapse:collapse}th,td{text-align:right;border-bottom:1px solid var(--line);padding:9px 7px;white-space:nowrap}th:first-child,td:first-child{text-align:left;max-width:420px;overflow:hidden;text-overflow:ellipsis}.good{color:var(--green)}.warn{color:var(--orange)}.metric-tags{display:flex;flex-wrap:wrap;gap:6px;margin-bottom:12px}.metric-tag{padding:4px 10px;border-radius:14px;border:1px solid var(--line);cursor:pointer;font-size:12px;user-select:none;transition:0.15s;color:var(--muted)}.metric-tag.active{border-color:var(--tag-color);background:color-mix(in srgb,var(--tag-color) 18%,transparent);color:#fff}@media(max-width:900px){.cards{grid-template-columns:repeat(2,1fr)}.filters,.grid{grid-template-columns:1fr}}
    </style><script src="https://cdn.jsdelivr.net/npm/chart.js@4"></script></head><body><div class="wrap"><h1>Meta 单素材表现</h1><div class="sub" id="coverage"></div><div class="filters"><div><div class="label">开始日期</div><input type="date" id="start"></div><div><div class="label">结束日期</div><input type="date" id="end"></div><div><div class="label">账户</div><select id="account"></select></div><div><div class="label">搜索素材</div><input id="search" placeholder="输入 V0057 / 题材 / 版本名"></div></div><div class="cards" id="cards"></div><div class="grid"><div class="panel"><h2>每日花费 / 收入趋势</h2><div class="metric-tags" id="metricTags"></div><div class="chart-wrap"><canvas id="trend"></canvas></div></div><div class="panel"><h2>诊断提示</h2><div id="insight"></div></div></div><div class="panel" style="margin-top:14px"><h2>素材排行（点击行查看单素材趋势）</h2><table><thead><tr><th>素材</th><th>账户</th><th>天数</th><th>花费</th><th>展示</th><th>点击</th><th>CTR</th><th>安装</th><th>购买</th><th>收入</th><th>ROAS</th></tr></thead><tbody id="table"></tbody></table></div><div class="panel" id="detailPanel" style="margin-top:14px;display:none"><h2 id="detailTitle">单素材趋势</h2><div class="sub" id="detailMetrics"></div><div class="metric-tags" id="metricTagsDetail"></div><div class="chart-wrap"><canvas id="detailTrend"></canvas></div></div></div><script>const D=__DATA__;const $=x=>document.getElementById(x);const fmt=(n,d=0)=>Number(n||0).toLocaleString('zh-CN',{maximumFractionDigits:d});const money=n=>'$'+fmt(n,2);
const METRICS={spend:{label:'花费',color:'#5b8cff',yAxis:'yMoney',format:v=>money(v)},revenue:{label:'收入',color:'#29d391',yAxis:'yMoney',format:v=>money(v)},installs:{label:'安装',color:'#ffb15c',yAxis:'yCount',format:v=>fmt(v)},purchases:{label:'购买',color:'#a78bfa',yAxis:'yCount',format:v=>fmt(v)},impressions:{label:'展示',color:'#22d3ee',yAxis:'yCount',format:v=>fmt(v)},clicks:{label:'点击',color:'#f472b6',yAxis:'yCount',format:v=>fmt(v)},cpi:{label:'CPI',color:'#ef4444',yAxis:'yMoney',format:v=>money(v),computed:d=>d.installs>0?d.spend/d.installs:null},cpa:{label:'CPA',color:'#eab308',yAxis:'yMoney',format:v=>money(v),computed:d=>d.purchases>0?d.spend/d.purchases:null},roas:{label:'ROAS',color:'#f8fafc',yAxis:'yRatio',format:v=>fmt(v,2),computed:d=>d.spend>0?d.revenue/d.spend:null},ctr:{label:'CTR',color:'#34d399',yAxis:'yRatio',format:v=>fmt(v,2)+'%',computed:d=>d.impressions>0?d.clicks/d.impressions*100:null}};
let activeMetrics=new Set(['spend','revenue']);let mainChart=null,detailChart=null,lastDetailAdId=null;
$('start').value=D.rows[0].report_date;$('end').value=D.rows.at(-1).report_date;$('account').innerHTML='<option value="">全部账户</option>'+D.accounts.map(x=>`<option>${x.account_name}</option>`).join('');$('coverage').textContent=`数据覆盖 ${$('start').value} 至 ${$('end').value} · 上海时区 · Meta 全版位汇总（可能包含 Facebook / Instagram / Audience Network） · 7天点击/1天浏览归因`;
function filtered(){let s=$('start').value,e=$('end').value,a=$('account').value,k=$('search').value.toLowerCase();return D.rows.filter(r=>r.report_date>=s&&r.report_date<=e&&(!a||r.account_name===a)&&(!k||(r.ad_name||'').toLowerCase().includes(k)))}
function buildMetricTags(){let h='';for(let[k,m]of Object.entries(METRICS)){let c=activeMetrics.has(k)?'active':'';h+='<span class="metric-tag '+c+'" data-key="'+k+'" style="--tag-color:'+m.color+'">'+m.label+'</span>'}['metricTags','metricTagsDetail'].forEach(id=>{let el=$(id);if(!el)return;el.innerHTML=h;el.querySelectorAll('.metric-tag').forEach(t=>t.addEventListener('click',()=>{let k=t.dataset.key;if(activeMetrics.has(k)){if(activeMetrics.size>1)activeMetrics.delete(k)}else activeMetrics.add(k);buildMetricTags();drawMain();if(lastDetailAdId)requestAnimationFrame(drawDetail)}))})}function drawChart(cid,days){let c=$(cid);let ex=cid==='trend'?mainChart:detailChart;if(ex)ex.destroy();let ctx=c.getContext('2d');let ds=[],mu=false,cu=false;for(let k of activeMetrics){let m=METRICS[k];if(m.yAxis==='yMoney')mu=true;else cu=true;ds.push({label:m.label,data:days.map(d=>m.computed?m.computed(d):(d[k]||0)),borderColor:m.color,backgroundColor:m.color+'30',yAxisID:m.yAxis,tension:.3,pointRadius:0,pointHoverRadius:5,pointHoverBackgroundColor:m.color,borderWidth:2})}let sc={x:{ticks:{color:'#8fa6c6',maxTicksLimit:8,maxRotation:0},grid:{display:false}}};if(mu){sc.yMoney={type:'linear',position:'left',title:{display:true,text:'金额 ($)',color:'#8fa6c6',font:{size:11}},ticks:{color:'#8fa6c6',font:{size:10},callback:v=>'$'+fmt(v)},grid:{color:'#25365440'}}}if(cu){sc.yCount={type:'linear',position:'right',title:{display:true,text:'数量 / 比率',color:'#8fa6c6',font:{size:11}},ticks:{color:'#8fa6c6',font:{size:10},callback:v=>fmt(v)},grid:{display:false}}}let ch=new Chart(ctx,{type:'line',data:{labels:days.map(d=>d.date),datasets:ds},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:false},tooltip:{backgroundColor:'#111e33',titleColor:'#edf4ff',bodyColor:'#edf4ff',borderColor:'#253654',borderWidth:1,padding:10,titleFont:{size:13},bodyFont:{size:12},callbacks:{title:items=>items.length?'日期：'+items[0].label:'',label:item=>{let m=METRICS[item.dataset.label.toLowerCase()]||Object.values(METRICS).find(x=>x.label===item.dataset.label);return ' '+item.dataset.label+'：'+(m?m.format(item.raw):fmt(item.raw,2))}}}},scales:sc}});if(cid==='trend')mainChart=ch;else detailChart=ch}
function aggDaily(rows){let dm={};rows.forEach(x=>{let d=dm[x.report_date]??={date:x.report_date,spend:0,revenue:0,installs:0,purchases:0,impressions:0,clicks:0};d.spend+=Number(x.spend||0);d.revenue+=Number(x.purchase_value||0);d.installs+=Number(x.app_installs||0);d.purchases+=Number(x.purchases||0);d.impressions+=Number(x.impressions||0);d.clicks+=Number(x.clicks||0)});return Object.values(dm).sort((a,b)=>a.date.localeCompare(b.date))}
function drawMain(){drawChart('trend',aggDaily(filtered()))}
function shortAcct(n){return String(n||'未命名').replace(/^.*?心动防线[-_]?/,'')||String(n||'未命名')}function dayCount(first,last){if(!first||!last)return 0;return Math.round((new Date(last+'T00:00:00')-new Date(first+'T00:00:00'))/86400000)+1}
function drawDetail(){if(!lastDetailAdId)return;let r=filtered().filter(x=>x.ad_id===lastDetailAdId);if(!r.length)return;drawChart('detailTrend',aggDaily(r))}function showDetail(adId){let r=filtered().filter(x=>x.ad_id===adId);if(!r.length)return;let sp=r.reduce((a,x)=>a+Number(x.spend||0),0),rev=r.reduce((a,x)=>a+Number(x.purchase_value||0),0),imp=r.reduce((a,x)=>a+Number(x.impressions||0),0),clk=r.reduce((a,x)=>a+Number(x.clicks||0),0);$('detailPanel').style.display='block';$('detailTitle').textContent='单素材趋势 · '+(r[0].ad_name||adId);$('detailMetrics').textContent=`广告 ID ${adId} · 花费 ${money(sp)} · 收入 ${money(rev)} · ROAS ${fmt(rev/Math.max(.01,sp),2)} · CTR ${fmt(clk/Math.max(1,imp)*100,2)}%`;lastDetailAdId=adId;requestAnimationFrame(()=>{if($('detailPanel').style.display!=='none')drawChart('detailTrend',aggDaily(r))});$('detailPanel').scrollIntoView({behavior:'smooth',block:'start'})}
function render(){let r=filtered(),sum=k=>r.reduce((a,x)=>a+Number(x[k]||0),0),sp=sum('spend'),rev=sum('purchase_value'),imp=sum('impressions'),clk=sum('clicks'),inst=sum('app_installs'),pur=sum('purchases');let vals=[['花费',money(sp)],['展示',fmt(imp)],['点击率',fmt(clk/Math.max(1,imp)*100,2)+'%'],['安装',fmt(inst)],['购买',fmt(pur)],['ROAS',fmt(rev/Math.max(.01,sp),2)]];$('cards').innerHTML=vals.map(x=>`<div class="card"><div class="label">${x[0]}</div><div class="value">${x[1]}</div></div>`).join('');$('detailPanel').style.display='none';lastDetailAdId=null;buildMetricTags();drawMain();let m={};r.forEach(x=>{let z=m[x.ad_id]??={adId:x.ad_id,name:x.ad_name,account:x.account_name,firstDate:x.report_date,lastDate:x.report_date,spend:0,impressions:0,clicks:0,installs:0,purchases:0,revenue:0};if(x.report_date<z.firstDate)z.firstDate=x.report_date;if(x.report_date>z.lastDate)z.lastDate=x.report_date;['spend','impressions','clicks','purchases'].forEach(k=>z[k]+=Number(x[k]||0));z.installs+=Number(x.app_installs||0);z.revenue+=Number(x.purchase_value||0)});let top=Object.values(m).sort((a,b)=>b.spend-a.spend).slice(0,50);$('table').innerHTML=top.map(x=>`<tr data-ad="${x.adId}" style="cursor:pointer"><td title="${x.name||''}">${x.name||'未命名'}</td><td style='font-size:11px;color:var(--muted)'>${shortAcct(x.account)}</td><td>${dayCount(x.firstDate,x.lastDate)}</td><td>${money(x.spend)}</td><td>${fmt(x.impressions)}</td><td>${fmt(x.clicks)}</td><td>${fmt(x.clicks/Math.max(1,x.impressions)*100,2)}%</td><td>${fmt(x.installs)}</td><td>${fmt(x.purchases)}</td><td>${money(x.revenue)}</td><td class="${x.revenue/x.spend>=1?'good':'warn'}">${fmt(x.revenue/Math.max(.01,x.spend),2)}</td></tr>`).join('');$('table').querySelectorAll('tr[data-ad]').forEach(tr=>tr.addEventListener('click',()=>showDetail(tr.dataset.ad)));let winners=top.filter(x=>x.spend>=100&&x.revenue/x.spend>=1).length,burn=top.filter(x=>x.spend>=100&&x.revenue/x.spend<.5).length;$('insight').innerHTML=`<p><b>${winners}</b> 个高花费素材 ROAS ≥ 1，可优先扩量。</p><p><b>${burn}</b> 个高花费素材 ROAS &lt; 0.5，建议复核受众、版位和前三秒。</p><p>当前筛选覆盖 <b>${Object.keys(m).length}</b> 个广告素材，覆盖 <b>${new Set(Object.values(m).map(x=>x.account)).size}</b> 个账户；当天数据为未完结日。(r='+r.length+' m='+Object.keys(m).length+')'</p>`}
['start','end','account','search'].forEach(x=>$(x).addEventListener('input',render));render();</script></body></html>'''.replace('__DATA__',data)
    html = re.sub(r"\(r='\+r\.length\+' m='\+Object\.keys\(m\)\.length\+'\)'", "", html)
    HTML.write_text(html,encoding='utf-8')

def main():
    conn=sqlite3.connect(DB); conn.row_factory=sqlite3.Row
    rows=q(conn,"SELECT report_date,account_name,campaign_name,adset_name,ad_id,ad_name,creative_id,spend,impressions,reach,clicks,ctr,cpm,cpc,app_installs,registrations,purchases,purchase_value,video_plays,thruplays,video_p25,video_p50,video_p75,video_p100,is_partial_day FROM meta_ad_daily ORDER BY report_date,account_name,ad_id")
    daily=q(conn,"SELECT report_date,ROUND(SUM(spend),2) spend,ROUND(SUM(purchase_value),2) revenue,SUM(app_installs) installs,SUM(purchases) purchases FROM meta_ad_daily GROUP BY report_date ORDER BY report_date")
    creatives=q(conn,"""SELECT ad_name,ad_id,MIN(report_date) first_date,MAX(report_date) last_date,COUNT(*) days,ROUND(SUM(spend),2) spend,SUM(impressions) impressions,SUM(clicks) clicks,ROUND(100.0*SUM(clicks)/NULLIF(SUM(impressions),0),2) ctr,SUM(app_installs) installs,SUM(purchases) purchases,ROUND(SUM(purchase_value),2) revenue,ROUND(SUM(purchase_value)/NULLIF(SUM(spend),0),2) roas,ROUND(SUM(spend)/NULLIF(SUM(app_installs),0),2) cpi,ROUND(SUM(spend)/NULLIF(SUM(purchases),0),2) cpa FROM meta_ad_daily GROUP BY ad_id,ad_name ORDER BY spend DESC""")
    accounts=q(conn,"""SELECT account_name,MIN(report_date) first_date,MAX(report_date) last_date,ROUND(SUM(spend),2) spend,SUM(impressions) impressions,SUM(clicks) clicks,SUM(app_installs) installs,SUM(purchases) purchases,ROUND(SUM(purchase_value),2) revenue,ROUND(SUM(purchase_value)/NULLIF(SUM(spend),0),2) roas FROM meta_ad_daily GROUP BY account_id,account_name ORDER BY spend DESC""")
    build_excel(rows,daily,creatives,accounts); build_html(rows,daily,creatives,accounts); shutil.copy2(DB,DB_COPY)
    check=load_workbook(XLSX,data_only=False,read_only=True); assert set(["看板","日明细","素材汇总","账户汇总","口径说明"]).issubset(check.sheetnames); check.close()
    print(json.dumps({"rows":len(rows),"creatives":len(creatives),"accounts":len(accounts),"from":rows[0]['report_date'],"to":rows[-1]['report_date'],"xlsx":str(XLSX),"html":str(HTML),"db":str(DB_COPY)},ensure_ascii=False,indent=2))
if __name__=='__main__': main()
